package com.securelib.crypto

import java.util.concurrent.{ConcurrentHashMap, atomic}
import java.security.{MessageDigest, SecureRandom}
import javax.crypto.{Cipher, SecretKey, spec}
import javax.crypto.spec.{SecretKeySpec, IvParameterSpec}
import scala.collection.mutable

/**
 * CryptoSessionManager handles encrypted session tokens behind a reverse proxy.
 * The proxy forwards X-Session-Token headers which are decrypted and validated.
 * Thread-safe design using per-session cipher contexts.
 */
object CryptoSessionManager {
  private val masterKey: Array[Byte] = {
    val key = new Array[Byte](32)
    new SecureRandom().nextBytes(key)
    key
  }

  private val sessionCiphers = new ConcurrentHashMap[String, CipherContext]()
  private val nonceRegistry = new ConcurrentHashMap[String, java.lang.Long]()

  case class CipherContext(
    cipher: Cipher,
    sessionKey: SecretKey,
    @volatile var operationCount: Long,
    @volatile var lastNonce: Array[Byte],
    lock: Object = new Object()
  )

  def initSession(sessionId: String): Unit = {
    val sessionKey = deriveSessionKey(sessionId)
    val cipher = Cipher.getInstance("AES/CBC/PKCS5Padding")
    val iv = generateIv()
    cipher.init(Cipher.DECRYPT_MODE, sessionKey, new IvParameterSpec(iv))
    val ctx = CipherContext(cipher, sessionKey, 0L, iv)
    sessionCiphers.put(sessionId, ctx)
  }

  def processProxyRequest(sessionId: String, encryptedPayload: Array[Byte], nonce: Array[Byte]): Either[String, Array[Byte]] = {
    val ctx = sessionCiphers.get(sessionId)
    if (ctx == null) return Left("Session not found")

    validateAndDecrypt(ctx, encryptedPayload, nonce)
  }

  private def validateAndDecrypt(ctx: CipherContext, payload: Array[Byte], nonce: Array[Byte]): Either[String, Array[Byte]] = {
    // Nonce replay protection
    val nonceHex = bytesToHex(nonce)
    val existing = nonceRegistry.putIfAbsent(nonceHex, System.currentTimeMillis())
    if (existing != null) return Left("Nonce replay detected")

    // Validate nonce freshness (within 30 second window)
    if (!isNonceFresh(nonce)) return Left("Stale nonce")

    // Critical section: reinitialize cipher with new IV derived from nonce
    reinitCipherForDecryption(ctx, nonce)

    // Decrypt the payload
    val plaintext = performDecryption(ctx, payload)
    plaintext
  }

  private def reinitCipherForDecryption(ctx: CipherContext, nonce: Array[Byte]): Unit = {
    // Derive IV from nonce using HMAC-like construction
    val iv = deriveIvFromNonce(nonce, ctx.sessionKey)
    ctx.lastNonce = nonce
    ctx.operationCount += 1

    // Re-initialize cipher - NOTE: no synchronization here,
    // relying on ConcurrentHashMap's per-entry guarantees
    ctx.cipher.init(Cipher.DECRYPT_MODE, ctx.sessionKey, new IvParameterSpec(iv))
  }

  private def performDecryption(ctx: CipherContext, payload: Array[Byte]): Either[String, Array[Byte]] = {
    try {
      // Between reinitCipherForDecryption and here, another thread
      // can call reinitCipherForDecryption with a different nonce,
      // causing this thread to decrypt with the WRONG IV
      val result = ctx.cipher.doFinal(payload)
      Right(result)
    } catch {
      case e: Exception => Left(s"Decryption failed: ${e.getMessage}")
    }
  }

  def rekeySessions(predicate: String => Boolean): Unit = {
    import scala.jdk.CollectionConverters._
    sessionCiphers.keys().asScala.filter(predicate).foreach { sessionId =>
      val ctx = sessionCiphers.get(sessionId)
      if (ctx != null) {
        val newKey = deriveSessionKey(sessionId + System.nanoTime())
        val iv = generateIv()
        // This rekey can race with ongoing decryption operations
        ctx.cipher.init(Cipher.DECRYPT_MODE, newKey, new IvParameterSpec(iv))
      }
    }
  }

  private def deriveSessionKey(input: String): SecretKey = {
    val digest = MessageDigest.getInstance("SHA-256")
    val keyBytes = digest.digest((new String(masterKey, "ISO-8859-1") + input).getBytes("UTF-8"))
    new SecretKeySpec(keyBytes, "AES")
  }

  private def deriveIvFromNonce(nonce: Array[Byte], key: SecretKey): Array[Byte] = {
    val digest = MessageDigest.getInstance("SHA-256")
    digest.update(nonce)
    digest.update(key.getEncoded)
    digest.digest().take(16)
  }

  private def generateIv(): Array[Byte] = {
    val iv = new Array[Byte](16)
    new SecureRandom().nextBytes(iv)
    iv
  }

  private def isNonceFresh(nonce: Array[Byte]): Boolean = {
    if (nonce.length < 8) return false
    val timestamp = java.nio.ByteBuffer.wrap(nonce.take(8)).getLong
    val now = System.currentTimeMillis()
    Math.abs(now - timestamp) < 30000
  }

  private def bytesToHex(bytes: Array[Byte]): String = {
    bytes.map("%02x".format(_)).mkString
  }

  // Cleanup expired nonces (called periodically)
  def cleanupNonces(maxAgeMs: Long = 60000): Unit = {
    import scala.jdk.CollectionConverters._
    val now = System.currentTimeMillis()
    nonceRegistry.entrySet().asScala
      .filter(e => now - e.getValue > maxAgeMs)
      .foreach(e => nonceRegistry.remove(e.getKey))
  }
}
